$artjson["ART_ru_general_a_1"] = "此规则与条款将适用于本公司所有的投注种类。会员们有责任确保您获知所有的规则与条款，我们保留随时修改条款的权利，并且会将修改的内容公布在本网站上。公布在网站公告上的信息可作为投注附加的规则与条款，若有任何差异或矛盾的地方，将以附加信息为准。";
$artjson["ART_ru_general_a_2"] = "本公司对此条款视为公平公正的，若您有任何意见或疑问，您可以联络我们的客服部，我们的客服团队将热诚协助每位客户，并确保能及时友善的解决您的问题。对于任何错误或争论，我们的客服团队将竭力提供服务。";
$artjson["ART_ru_general_a_3"] = "所有的条款用于在会员与公司之间建立一般的原则。对产生的任何争议，希望通过该条款让双方都得到满意的解决方案。";
$artjson["ART_ru_general_b"] = "一般体育规则";
$artjson["ART_ru_general_b_p"] = "所有在本公司进行的投注都需要依照以下规则与条款处理。在个别体育项目里注明的规则将视为体育主要规则:";
$artjson["ART_ru_general_b_1"] = "所有投注项目的最高和最低投注额将由公司决定，如有任何更改无需提前通知。";
$artjson["ART_ru_general_b_2"] = "会员申请账户时需提供正确的个人信息，本公司对提供伪造或错误信息的账户将不负任何责任。";
$artjson["ART_ru_general_b_3"] = "会员将全权负责账户提交的所有交易。在投注前请仔细检查选项，一旦投注提交成功后，将无法更改或取消。公司对会员自身原因造成的遗漏或重复投注不负任何责任。会员可以在\"交易记录\"中查看详情确保所有提交的注单已成功。";
$artjson["ART_ru_general_b_4"] = "在任何投诉中，如果在公司的数据库中没有存储任何记录，公司将不接受也不认可任何会员提供的复印件或单据。";
$artjson["ART_ru_general_b_5"] = "公司保留在任何时候关闭或冻结会员账号的权利。";
$artjson["ART_ru_general_b_6"] = "公司保留在任何时候暂停/中止会员对任何盘口进行投注的权利。";
$artjson["ART_ru_general_b_7"] = "公司保留对已预先知道赛果的投注作出取消的权利。如果由于\"滚球现场\"延迟而引起盘口的赔率错误，此期间的注单将视为无效。 ";
$artjson["ART_ru_general_b_8"] = "关于赛事的信息，例如日期，时间;比分，数据统计，红牌和中立场等信息仅供会员参考，公司对提供此信息的准确性不负任何责任。";
$artjson["ART_ru_general_b_9"] = "如果比赛或赛事取消，中断或延迟并且没有在官方指定开球时间的36小时内重新开始，所有该场赛事的投注即被视为无效且取消，除非在个别体育规则里另有指定注明。 某些无条件终止的盘口将会相应地结算。单独的体育规则中对此类盘口的结算程序做了说明。公司取消该赛事所有注单的结果被视为最终决定，无需参考官方赛事裁判或相关部门的决定。连串投注将会继续按照注单剩余赛事的赛果结算，该取消赛事的赔率将会按照1计算。";
$artjson["ART_ru_general_b_10"] = "如果比赛或是赛事取消，所有该场赛事的投注即被视为无效且取消，除非在个别体育规则里另有指定注明。对于取消的定义和处理本公司拥有最终解释权。";
$artjson["ART_ru_general_b_11"] = "如果对其它语言版本的信息或球赛队名有争议，请以英文网站的名称为准。";
$artjson["ART_ru_general_b_12"] = "由以下事件造成的任何损失，公司不赋予任何责任:";
$artjson["ART_ru_general_b_12_1"] = "公司的网站、服务器或网络中断。";
$artjson["ART_ru_general_b_12_2"] = "公司数据库、服务器丢失信息或信息遭受破坏。";
$artjson["ART_ru_general_b_12_3"] = "不法分子攻击网站、服务器或网络供应商。";
$artjson["ART_ru_general_b_12_4"] = "进入网站时由于网络供应商原因造成的网络缓慢。";
$artjson["ART_ru_general_b_13"] = "如果系统发生不可预知的事件而导致已投注的注单出现争议，公司将会根据数据库的资料为准。";
$artjson["ART_ru_general_b_14"] = "如果对此规则与条款的内容有任何疑义，请以公司的解释为准。";

$artjson["ART_ru_general_c"] = "赛果与派彩";
$artjson["ART_ru_general_c_1"] = "赛果均在赛事结束后判定，除非在个别体育规则里另有注明。赛果公布72小时后，若对任何赛果有争议，本公司将不认可。在赛果公布72小时内,除了任何体育纪律委员会所重新裁决之赛果，本公司只会修正人为、系统或参考赛果的相关网页失误等原因的错误。";
$artjson["ART_ru_general_c_2"] = "投注通常在赛事结束后派彩。但考虑到会员的利益，某些投注会在官方公布赛事结果之前就进行派彩。这些投注会在无条件确定结果的情况下派彩，可以包括被放弃，暂停或推迟的赛事。为此，公司保留对此而造成的错误进行更改的权利。";
$artjson["ART_ru_general_c_3"] = "派彩是根据官方来源或相关体育权威机构判定的结果为准。如果无法从相关体育权威机构判定结果，公司将会根据其他数据来源判定结果进行派彩，同时此数据会在被认定为合理的前提下。";
$artjson["ART_ru_general_c_4"] = "所有的交易将以公司最新备份数据记录为准，公司不接纳任何投诉或争议，除非会员提供交易记录的截图或影印证据，否则公司的数据记录将作为最终证明。";

$artjson["ART_ru_general_d"] = "滚球类型投注规则";
$artjson["ART_ru_general_d_p"] = "滚球投注是指对正在进行比赛的赛事进行投注。注单会在比赛开始后开始接收并且在盘口关盘后停止所有交易。个别体育会开出多个滚球种类的盘口供投注。";
$artjson["ART_ru_general_d_1"] = "所有滚球投注均需要遵守系统验收程序。这可能会导致每笔投注延迟确认或出现投注失败的情况。";
$artjson["ART_ru_general_d_2"] = "所有在注单上显示\"待确认\"的字眼则表示注单正在等待系统的判断投注是否成功。这表示注单在等待被确认或可能被取消。";
$artjson["ART_ru_general_d_3"] = "在赛事有事件发生或出现其他特殊情况时，所有待确认中的注单将不被确认并视为投注失败。";
$artjson["ART_ru_general_d_3_1"] = "足球 - 此事件可包含进球，红卡，点球或技术上问题等等。(其他例子并不一一详尽列出)";
$artjson["ART_ru_general_d_3_2"] = "其他体育项目 - 在投注确认之前，如果赔率发生变化或市场状态发生变动，待处理的投注将视为无效。";
$artjson["ART_ru_general_d_4"] = "当有重大事件发生时，会应用电视裁判助理（VAR）来判定，这可能会导致之前已确定的注单被取消。注单被取消始于重大事件发生的开端直到VAR的最终官方判定已宣布。";
$artjson["ART_ru_general_d_5"] = "在滚球投注中，本公司需强调以下条款，确保投注是按照正确的时间、金额和在正确的情况下进行:";
$artjson["ART_ru_general_d_5_1"] = "比赛赛果和入球时间以本公司网站公布的为准，我们不参考任何其它官方网站，体育网站，或\"即时比分\"等网站公布的赛果或入球时间。";
$artjson["ART_ru_general_d_5_2"] = "如果有合理的理由怀疑投注是在比赛时某个事件发生后才提交的，本公司将保留取消此注单且不需提供任何理由和证明的权利。";
$artjson["ART_ru_general_d_5_3"] = "如果出现网站无法更新比分、赔率或盘口的情况，本公司保留权利取消所有未确认且处理中的注单。";

$artjson["ART_ru_general_e"] = "有关时间规则";
$artjson["ART_ru_general_e_1"] = "如比赛在法定时间提前进行，在比赛开始前的投注依然有效，在比赛开始后的所有投注均视为无效(滚球投注另作别论)。";
$artjson["ART_ru_general_e_2"] = "足球赛事的正常完场时间包括任何球员伤停补时。";
$artjson["ART_ru_general_e_3"] = "除非在个别体育规则另有注明，加时得分则不计算在正常完场时间内。";

$artjson["ART_ru_general_f"] = "并列名次规则";
$artjson["ART_ru_general_f_1"] = "一场赛事的盘口产生2名或者以上的获胜者，那么赢利金额将减少。计算方法是将本金除以获胜者人数，然后乘以原赔率。这部分本金及赢利将返还给会员，剩余的本金将输掉。";
$artjson["ART_ru_general_f_2"] = "例如：";
$artjson["ART_ru_general_f_2_1"] = "第一阶段-您投注5.00英镑，赔率16.0（可能的赢利金额为75.00英镑）";
$artjson["ART_ru_general_f_2_2"] = "第二阶段-您投注的对象与另一名对象同时获胜";
$artjson["ART_ru_general_f_2_3"] = "第三阶段-您投注额的一半将会有原来的赔率（16.0）。因此，‘输赢’ 为 \u0024 2.50 x \u0024 16.0 = \u002437.50 [ 扣除 \u00242.50 的投注额 ] = \u002435.0";
$artjson["ART_ru_general_f_2_4"] = "如果有2名以上的获胜者，注金将会分成相应的等份";
$artjson["ART_ru_general_f_2_5"] = "实际上在2名获胜者的情况下，本金的一半（50%）将乘以原赔率，剩余的一半（50%）将输掉。";
$artjson["ART_ru_general_f_3"] = "并列名次规则将不适用于，如果我们最终决定，可由排名準則决定排序的赛事。（例如小组赛事）";

$artjson["ART_ru_general_g"] = "场地变更";
$artjson["ART_ru_general_g_1"] = "如果比赛场地有变更（主客队调换），所有此注单将被取消。";
$artjson["ART_ru_general_g_2"] = "本公司保留权利取消因更换场地而可能对赛事结果有影响的注单，例如：网球比赛更换场地表面。";
$artjson["ART_ru_general_g_3"] = "若比赛原定在中立场进行改为在非中立场进行且在本公司判定下对比赛没有影响，注单将继续保持有效。";
$artjson["ART_ru_general_g_4"] = "在个别体育项目里若有特别注明将覆盖以上规则。";

$artjson["ART_ru_general_h"] = "错误";
$artjson["ART_ru_general_h_1"] = "本公司力求错误发生的机率保持最低，但若有注单显然是在盘口有错误的情况下提交，我们将保留取消此注单的权利。错误的情况包括：";
$artjson["ART_ru_general_h_1_1"] = "赔率错误 （和市场上提供的有明显差别）；";
$artjson["ART_ru_general_h_1_2"] = "盘口信息错误， 例如：让球数，大小数等；";
$artjson["ART_ru_general_h_1_3"] = "赛事信息错误，例如：参赛队名或队员， 赛事日期或开赛时间。";
$artjson["ART_ru_general_h_2"] = "若因遇到以上的情况而需取消任何注单，我们会尽可能的与客户取得联系，有关讯息也会及时在公告栏里发布。";

$artjson["ART_ru_general_i"] = "异常投注行为";
$artjson["ART_ru_general_i_1"] = "对任何怀疑在投注时涉嫌作弊或破坏本公司投注平台的会员，公司有权在毫无警告或通知下取消此会员所有的注单并且冻结账户。异常行为包括使用任何设备，自动设备，软件，程序等方式干涉本网站的运作。";


/*help_term*/
